def parse_demo(msg,n,kind):
 pat=rf'Demo pair {n} {kind} \(\d+x\d+\):\n'
 start=re.search(pat,msg).end()
 tail=msg[start:]
 rows=[]
 for l in tail.splitlines():
  if not re.fullmatch(r'[0-9 ]+',l): break
  rows.append([int(x) for x in l.split()])
 return np.array(rows)
for i,n in [(7,1),(19,2),(23,3)]:
