def panel_scores(i,n):
 msg=''.join(p.get('text','') for p in records[i]['message']['content']); a=parse_demo(msg,n,'input'); b=parse_demo(msg,n,'output')
 tile=5; starts=list(range(1,a.shape[1]-1,tile+1)); bandstarts=list(range(1,a.shape[0]-1,tile+1))
 print('demo',n)
 for rs in bandstarts:
  outs=b[rs:rs+tile,1:6]
  scores=[np.sum(outs!=a[rs:rs+tile,s:s+tile]) for s in starts]
  print(rs, scores, 'matches',np.argmin(scores), 'vals', [a[rs:rs+tile,s:s+tile].tolist() for s in starts])
for i,n in [(7,1),(19,2),(23,3)]: panel_scores(i,n)

def get_panels(i,n):
 msg=''.join(p.get('text','') for p in records[i]['message']['content']); a=parse_demo(msg,n,'input'); b=parse_demo(msg,n,'output')
 tile=5; starts=list(range(1,a.shape[1]-1,6)); bandstarts=list(range(1,a.shape[0]-1,6))
 return [[a[rs:rs+5,s:s+5] for s in starts] for rs in bandstarts], [b[rs:rs+5,1:6] for rs in bandstarts]
def sym_scores(p):
 mask=p!=p[0,0] # foreground based on bg at corner
 return [np.sum(mask!=mask[::-1,:]),np.sum(mask!=mask[:,::-1]),np.sum(mask!=mask[::-1,::-1]), np.sum(mask!=mask.T)]
for i,n in [(7,1),(19,2),(23,3)]:
 panels,outs=get_panels(i,n); print('demo',n)
 for ri,(ps,out) in enumerate(zip(panels,outs)):
  sel=np.argmin([np.sum(p!=out) for p in ps]);
  print('row',ri+1,'sel',sel,[sym_scores(p) for p in ps], 'counts',[np.sum(p!=p[0,0]) for p in ps])

